import {REGIONS,RATES,SHINY_RATE,summonRoll,isShiny} from './model.mjs';
import {icon,drawMon,preload} from './art.mjs';
export class Summoning {
 constructor(game){this.g=game;this.gen=1;this.busy=false}
 render(){const g=this.g,featured=[150,249,384,487,643,716,791,888,1007][this.gen-1];return `${g.heading('LES PORTAILS DE LA TOUR','Le cercle d’invocation','Neuf régions à découvrir. Un seul ticket pour tous les portails.')}<div class="ticket-explainer"><div class="ticket-glyph"></div><div><strong>${g.state.tickets} tickets universels</strong><p>1 ticket = 1 invocation, dans le portail de ton choix.</p></div><button data-act="route" data-page="survival">Gagner des tickets ↗</button></div><div class="region-tabs">${REGIONS.map((r,i)=>`<button class="${i+1===this.gen?'selected':''}" data-act="portal" data-gen="${i+1}"><small>GÉN. ${i+1}</small>${r}</button>`).join('')}</div><section class="summon-showcase"><div class="portal-visual"><div class="portal-ring"></div><div class="portal-ring ring-two"></div><img class="portal-featured" src="${icon(String(featured))}" alt="${g.poke(featured).name}"><span class="portal-rune">✦</span></div><div class="portal-copy"><span class="eyebrow">PORTAIL ${REGIONS[this.gen-1].toUpperCase()}</span><h2>Les échos de<br>${REGIONS[this.gen-1]}</h2><p>Chaque invocation peut ouvrir la voie à un nouveau compagnon. Qui répondra à ton appel ?</p><span class="shiny-note">✧ Shiny : 1 % · en plus de la rareté</span><button class="primary summon-button" data-act="summon" ${g.state.tickets<1||!g.state.starter?'disabled':''}><span class="ticket-mark">▱</span> Invoquer un Pokémon <small>1 ticket universel</small></button><div class="portal-actions"><button class="text-button" data-act="rates">Voir tous les Pokémon et leurs taux →</button></div></div></section><section class="rates-panel"><div class="section-title"><h2>Les taux du portail</h2><span>Identiques sur les 9 portails</span></div><div class="rates-grid">${RATES.map(r=>`<div class="rate ${r.key}"><span>◆ ${r.name}</span><strong>${r.rate}<small>%</small></strong><i style="--rate:${r.rate}%;--rarity:${r.color}"></i></div>`).join('')}</div><p>Le shiny est tiré séparément avec une probabilité de 1 % : il conserve la rareté du Pokémon. Les légendaires incluent les fabuleux. Les espèces d’une même rareté ont toutes la même chance.</p></section><div class="summon-bottom"><section class="panel"><h3>Comment obtenir des tickets ?</h3><div class="earning-row"><span>✦</span><div><b>Survis dans les terres de cendre</b><p>1 ticket toutes les 20 secondes de survie.</p></div></div><div class="earning-row"><span>♜</span><div><b>Triomphe d’un gardien</b><p>2 tickets pour chaque étage vaincu.</p></div></div></section><section class="panel"><h3>Dernières invocations</h3><div class="summon-history">${g.state.history.slice(0,6).map(r=>`<button class="history-mon ${r.rarity}" data-act="inspect" data-key="${r.key}"><img src="${icon(r.key)}" alt="${g.poke(r.key).name}"><span>${g.poke(r.key).name}${isShiny(r.key)?' ✧':''}</span></button>`).join('')||'<p class="muted">Le cercle attend ta première invocation.</p>'}</div></section></div>`}
 async invoke(){const g=this.g;if(this.busy||!g.requireStarter())return;if(g.state.tickets<1)return g.toast('Il te faut un ticket universel. Gagne-en dans la tour ou en survie.');this.busy=true;const result=summonRoll(g.dex,this.gen),duplicate=g.state.roster.includes(result.key);g.state.tickets--;if(!duplicate)g.state.roster.push(result.key);else g.state.coins+=isShiny(result.key)?80:30;g.state.history.unshift(result);g.state.history=g.state.history.slice(0,30);g.save();preload([result.key]);g.openModal(`<div class="invocation-sequence ${result.rarity}" id="invocation-stage"><span class="eyebrow">LE PORTAIL S’ÉVEILLE</span><div class="invocation-vortex"><i></i><i></i><i></i><div class="invocation-orb">✦</div><div class="vortex-particles"></div></div><h2>Un écho traverse la tour…</h2><p>Ton nouveau compagnon approche.</p></div>`,{locked:true});g.audio.chime(result.rarity);const duration=g.state.settings.reducedMotion?100:1750;await new Promise(r=>setTimeout(r,duration));const rarity=g.rarity(result.rarity);g.openModal(`<div class="invocation-result ${result.rarity} ${isShiny(result.key)?'is-shiny':''}"><div class="reveal-rays"></div><span class="eyebrow">${duplicate?'UN VISAGE FAMILIER':'UNE NOUVELLE ALLIANCE'}</span><span class="rarity-tag ${result.rarity}">${rarity.name}${isShiny(result.key)?' · ✧ SHINY':''}</span><canvas class="reveal-mon" width="260" height="210" aria-label="${g.poke(result.key).name}"></canvas><h2>${g.poke(result.key).name}</h2><p>${duplicate?`Doublon converti en ${isShiny(result.key)?80:30} fragments.`:'A rejoint ta collection.'}</p>${isShiny(result.key)?'<p class="shiny-note">Une véritable variante chromatique · 1 % de chance</p>':''}<button class="primary" data-act="close-modal">Accueillir ${g.poke(result.key).name}</button><button data-act="summon-again" ${g.state.tickets<1?'disabled':''}>Invoquer à nouveau · 1 ticket</button></div>`,{onClose:()=>{if(g.page==='gacha')g.render()}});const canvas=g.modal.querySelector('canvas'),ctx=canvas.getContext('2d');const animate=t=>{if(!canvas.isConnected||!g.modal.open)return;ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,260,210);ctx.fillStyle='#060b1466';ctx.beginPath();ctx.ellipse(130,178,54,10,0,0,7);ctx.fill();drawMon(ctx,result.key,130,108,185,'Idle',0,t/1000);requestAnimationFrame(animate)};requestAnimationFrame(animate);this.busy=false}
 rates(){const g=this.g,pool=Object.values(g.dex).filter(p=>p.gen===this.gen);g.openModal(`<span class="eyebrow">TRANSPARENCE DES INVOCATIONS</span><h2>Portail ${REGIONS[this.gen-1]}</h2><p>Chaque espèce a le taux de sa rareté divisé par le nombre d’espèces de cette rareté. Le shiny ajoute un tirage indépendant à 1 %.</p><div class="all-rates">${RATES.map(r=>{const mons=pool.filter(p=>p.rarity===r.key),rate=r.rate/mons.length;return `<details><summary><span class="${r.key}">◆ ${r.name}</span><b>${r.rate} % · ${mons.length} espèces</b></summary><div class="rates-list">${mons.map(p=>`<div><span>${p.name}</span><b>${rate.toFixed(5)} %</b><small>dont shiny ${(rate*SHINY_RATE).toFixed(6)} %</small></div>`).join('')}</div></details>`}).join('')}</div>`)}
}
